var t=[{title:`Ce se numără ca HIIT`,text:`HIIT cere un efort greu pentru condiția ta actuală, urmat de obicei de un interval mai ușor, care îți permite să faci încă un efort bun. Respirația grea este de așteptat, dar pierderea controlului tehnicii nu. Grăbirea prin circuite nu dă automat același efect de antrenament ca intervalele aerobe structurate de intensitate mare.`},{title:`Ce este Tabata`,text:`Formatul clasic Tabata înseamnă opt runde de câte 20 de secunde de efort greu și 10 secunde de odihnă, patru minute în total. Cercetarea originală a folosit eforturi foarte intense de ciclism, așa că un circuit obișnuit 20/10 se numește mai corect „în stil Tabata”, dacă efortul nu este similar. Un protocol scurt are totuși nevoie de încălzire înainte și de refacere după.`},{title:`Cine ar trebui să înceapă mai simplu`,text:`Dacă revii după o pauză de la activitate sau înveți mișcări noi, câteva săptămâni de muncă aerobă confortabilă mai întâi te pot ajuta mai mult. Dacă ai o afecțiune medicală care ar putea fi afectată, întreabă-ți medicul înainte să începi. Burpee și săriturile nu sunt necesare pentru a face cardio intens, iar o bicicletă fixă poate fi mai sigură și mai ușor de controlat.`},{title:`Limitează munca grea`,text:`Începe cu intervale scurte pe care le poți face cu formă bună și lasă destule zile ușoare între sesiunile grele. Creșterea deodată a frecvenței, a intensității și a rundelor poate aduce oboseală fără beneficii suplimentare. HIIT este o opțiune alături de activitatea constantă, antrenamentul de forță și mersul de zi cu zi și poți ajunge în formă și fără el.`}];var a=[{label:`ACE: proiectarea intervalelor de intensitate mare`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`ACE: formatul original de intervale Tabata`,url:`https://www.acefitness.org/continuing-education/prosource/hiit-special-issue/3743/is-tabata-all-it-s-cracked-up-to-be/`},{label:`CDC: recomandări de activitate fizică pentru adulți`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var r={sections:t,sources:a};export{r as default,t as sections,a as sources};